SET plan_cache_mode=force_custom_plan; SET statement_timeout=120000; PREPARE hfs1579 AS SELECT id, version_id, data, last_updated, fhir_version, last_updated AS sort_key FROM resources WHERE tenant_id = $1 AND resource_type = $2 AND is_deleted = FALSE AND (id IN (SELECT resource_id FROM search_index WHERE tenant_id = $1 AND resource_type = $2 AND param_name = 'code' AND ((value_token_system IN ($5, 'urn:x-helios:implicit code system') AND value_token_code = $6)))) AND (last_updated < $3 OR (last_updated = $3 AND id > $4)) ORDER BY last_updated DESC, id ASC LIMIT 1001;
EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) EXECUTE hfs1579('default','Observation','2026-09-25T03:54:09.096186+00:00','d2dd7c21-142e-0e8c-6c9b-7a4b79e76392','http://loinc.org','8302-2');
